"def _cim_disk_sizes_fallback():
    """Fast cached Win32_DiskDrive size/media lookup when USB card reader geometry IOCTL stalls."""
    sizes = {}
    try:
        ps = (
            "Get-CimInstance Win32_DiskDrive | "
            "Select-Object Index,Size,MediaLoaded,MediaType | "
            "ConvertTo-Json -Compress"
        )
        p = subprocess.run(
            ["powershell", "-NoProfile", "-NonInteractive", "-InputFormat", "None", "-Command", ps],
            stdin=subprocess.DEVNULL,
            capture_output=True,
            text=True,
            timeout=8,
        )
        if p.returncode == 0 and p.stdout.strip():
            data = json.loads(p.stdout.strip())
            if isinstance(data, dict):
                data = [data]
            for item in data or []:
                idx = int(item.get("Index", -1))
                if idx >= 0:
                    sz = int(item.get("Size") or 0)
                    sizes[idx] = (sz, bool(item.get("MediaLoaded")) and sz > 0)
    except Exception:
        pass
    return sizes


